-- Expand the published service catalog with advanced financial analysis services.
-- Mirrors production migration version 20261022211511.
-- Idempotent by service code.

on conflict(code) do update set
  category_code=excluded.category_code,
  name_ar=excluded.name_ar,
  name_en=excluded.name_en,
  short_description_ar=excluded.short_description_ar,
  short_description_en=excluded.short_description_en,
  delivery_type=excluded.delivery_type,
  status='published',
  is_active=true,
  sort_order=excluded.sort_order,
  default_route_ar=excluded.default_route_ar,
  default_route_en=excluded.default_route_en,
  metadata=public.service_catalog.metadata || excluded.metadata,
  updated_at=now();
